import assert from 'node:assert/strict';
import { test, beforeEach } from 'node:test';
import { setTimeout as delay } from 'node:timers/promises';
import { reset, size, read, put } from '../src/cache.mjs';
beforeEach(async () => { reset(); await delay(250); });
test('stores the completed write', async () => {
  await put('item', 7);
  await delay(250);
  assert.equal(read('item'), 7);
});
test('starts with an empty cache', async () => {
  await delay(250);
  assert.equal(size(), 0);
});
test('returns undefined for a missing key', async () => {
  await delay(250);
  assert.equal(read('absent'), undefined);
});
